GPU_MEM_SIZE = 80  # GB


# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Minimize a feasible KVPR bound, then apply deterministic minimax moves."""
    eps = 1e-8
    if gpu_num <= 0:
        raise ValueError("gpu_num must be positive")

    n = len(models)
    if n == 0:
        return {g: [] for g in range(gpu_num)}

    loads = [float(m.req_rate / m.slo) for m in models]
    sizes = [float(m.model_size) for m in models]
    if any(s >= GPU_MEM_SIZE - eps for s in sizes):
        raise ValueError("A model leaves no positive KV-cache memory on a GPU")

    def value(state):
        ans = 0.0
        for group in state:
            free = GPU_MEM_SIZE - sum(sizes[i] for i in group)
            if free <= eps:
                return float("inf")
            ans = max(ans, sum(loads[i] for i in group) / free)
        return ans

    # Several deterministic constructions provide a robust feasible incumbent.
    orders = [
        sorted(range(n), key=lambda i: (-loads[i], -sizes[i], i)),
        sorted(range(n), key=lambda i: (-sizes[i], -loads[i], i)),
        sorted(range(n), key=lambda i: (
            -(loads[i] / max(GPU_MEM_SIZE - sizes[i], eps)), -sizes[i], i)),
        sorted(range(n), key=lambda i: (
            -(loads[i] / max(sizes[i], eps)), -loads[i], -sizes[i], i)),
    ]

    best = None
    best_value = float("inf")
    for order in orders:
        state = [[] for _ in range(gpu_num)]
        used = [0.0] * gpu_num
        demand = [0.0] * gpu_num
        feasible = True
        for i in order:
            choices = []
            for g in range(gpu_num):
                free = GPU_MEM_SIZE - used[g] - sizes[i]
                if free > eps:
                    projected = (demand[g] + loads[i]) / free
                    other = max(
                        [demand[h] / (GPU_MEM_SIZE - used[h])
                         for h in range(gpu_num) if h != g] + [0.0]
                    )
                    choices.append((max(projected, other), projected, -free, g))
            if not choices:
                feasible = False
                break
            g = min(choices)[3]
            state[g].append(i)
            used[g] += sizes[i]
            demand[g] += loads[i]
        if feasible and value(state) < best_value:
            best = state
            best_value = value(state)

    if best is None:
        raise ValueError("Unable to find a feasible positive-residual-memory placement")

    lower = max(
        [loads[i] / (GPU_MEM_SIZE - sizes[i]) for i in range(n)] +
        [sum(loads) / max(gpu_num * GPU_MEM_SIZE - sum(sizes), eps), 0.0]
    )

    # A globally coupled fixed-bound MILP.  A feasible incumbent from a timed
    # solve is accepted only after exact verification.
    try:
        import numpy as np
        from scipy.optimize import milp, Bounds, LinearConstraint
        from scipy.sparse import lil_matrix

        v = n * gpu_num
        A = lil_matrix((n + 2 * gpu_num, v), dtype=float)
        for i in range(n):
            for g in range(gpu_num):
                A[i, i * gpu_num + g] = 1.0
        for g in range(gpu_num):
            for i in range(n):
                k = i * gpu_num + g
                A[n + g, k] = sizes[i]

        lo, hi = lower, best_value
        for _ in range(20):
            mid = (lo + hi) * 0.5
            for g in range(gpu_num):
                for i in range(n):
                    A[n + gpu_num + g, i * gpu_num + g] = (
                        loads[i] + mid * sizes[i]
                    )

            lb = np.r_[np.ones(n), np.full(gpu_num, -np.inf),
                       np.full(gpu_num, -np.inf)]
            ub = np.r_[np.ones(n), np.full(gpu_num, GPU_MEM_SIZE - eps),
                       np.full(gpu_num, GPU_MEM_SIZE * mid)]
            result = milp(
                np.zeros(v), integrality=np.ones(v), bounds=Bounds(0, 1),
                constraints=LinearConstraint(A.tocsr(), lb, ub),
                options={"time_limit": 0.12}
            )

            if result.x is None:
                lo = mid
                continue

            trial = [[] for _ in range(gpu_num)]
            valid = True
            for i in range(n):
                row = result.x[i * gpu_num:(i + 1) * gpu_num]
                g = int(np.argmax(row))
                if row[g] < 0.5:
                    valid = False
                    break
                trial[g].append(i)

            if valid and value(trial) <= mid + 1e-7:
                best = trial
                best_value = value(trial)
                hi = mid
            else:
                lo = mid
    except Exception:
        pass

    # Best-improving one-model moves are cheap and can correct a rounded MILP
    # solution without risking feasibility.
    for _ in range(min(4, n + 1)):
        current = value(best)
        worst = max(
            range(gpu_num),
            key=lambda g: sum(loads[i] for i in best[g]) /
            (GPU_MEM_SIZE - sum(sizes[i] for i in best[g]))
        )
        chosen = None
        chosen_value = current
        for i in best[worst]:
            for g in range(gpu_num):
                if g == worst:
                    continue
                if GPU_MEM_SIZE - sum(sizes[j] for j in best[g]) - sizes[i] <= eps:
                    continue
                trial = [x[:] for x in best]
                trial[worst].remove(i)
                trial[g].append(i)
                trial_value = value(trial)
                if trial_value < chosen_value - 1e-12:
                    chosen_value = trial_value
                    chosen = trial
        if chosen is None:
            break
        best = chosen

    return {g: [models[i] for i in best[g]] for g in range(gpu_num)}


